import { describe, expect, it, vi } from "vitest";

import { Sessions } from "../src/v3/resources/sessions.js";

describe("v3 BYOK settings", () => {
  it("adds useOwnKey when configured on the sessions resource", async () => {
    const post = vi.fn(async (_path: string, body: unknown) => body);
    const sessions = new Sessions({ post } as any, { useOwnKey: true });

    await sessions.create({ task: "Find pricing" });

    expect(post).toHaveBeenCalledWith("/sessions", {
      task: "Find pricing",
      useOwnKey: true,
    });
  });

  it("lets per-request useOwnKey override the default", async () => {
    const post = vi.fn(async (_path: string, body: unknown) => body);
    const sessions = new Sessions({ post } as any, { useOwnKey: true });

    await sessions.create({ task: "Find pricing", useOwnKey: false });

    expect(post).toHaveBeenCalledWith("/sessions", {
      task: "Find pricing",
      useOwnKey: false,
    });
  });
});

import { describe, expect, it, vi } from "vitest";

import { applyX402MaxPaymentUsd } from "../src/core/x402.js";

describe("x402 payment cap", () => {
  it("filters v2 and v1 payment requirements above the USD cap", () => {
    const registerPolicy = vi.fn();
    const client = { registerPolicy };

    applyX402MaxPaymentUsd(client, 0.75);

    const policy = registerPolicy.mock.calls[0][0] as (
      version: number,
      requirements: unknown[],
    ) => unknown[];
    expect(
      policy(2, [
        { amount: "750000" },
        { amount: "750001" },
        { amount: "not-a-number" },
      ]),
    ).toEqual([{ amount: "750000" }]);
    expect(
      policy(1, [
        { maxAmountRequired: "749999" },
        { maxAmountRequired: "1000000" },
      ]),
    ).toEqual([{ maxAmountRequired: "749999" }]);
  });

  it("keeps decimal caps exact despite float error", () => {
    const registerPolicy = vi.fn();
    applyX402MaxPaymentUsd({ registerPolicy }, 0.000249);
    const policy = registerPolicy.mock.calls[0][0] as (v: number, r: unknown[]) => unknown[];
    expect(policy(2, [{ amount: "249" }])).toEqual([{ amount: "249" }]);
  });

  it.each([0, -1, Number.NaN, Number.POSITIVE_INFINITY])(
    "rejects invalid caps (%s)",
    (cap) => {
      expect(() => applyX402MaxPaymentUsd({ registerPolicy: vi.fn() }, cap)).toThrow(
        /positive finite number/,
      );
    },
  );

  it("rejects clients that cannot enforce a policy", () => {
    expect(() => applyX402MaxPaymentUsd({}, 1)).toThrow(/does not support payment policies/);
  });
});

"""Unit tests for the optional x402 payment ceiling."""

from __future__ import annotations

from types import SimpleNamespace
from typing import Any

import pytest

from browser_use_sdk._core import x402 as x402_helpers


class FakeRequirement:
    def __init__(self, amount: int) -> None:
        self.amount = amount

    def get_amount(self) -> int:
        return self.amount


class FakeClient:
    def __init__(self) -> None:
        self.policy: Any = None

    def register_policy(self, policy: Any) -> FakeClient:
        self.policy = policy
        return self


def test_x402_payment_cap_filters_requirements(monkeypatch: pytest.MonkeyPatch) -> None:
    def max_amount(limit: int) -> Any:
        return lambda _version, requirements: [
            item for item in requirements if item.get_amount() <= limit
        ]

    real_import = x402_helpers.importlib.import_module

    def fake_import(name: str) -> Any:
        if name == "x402":
            return SimpleNamespace(max_amount=max_amount)
        return real_import(name)

    monkeypatch.setattr(x402_helpers.importlib, "import_module", fake_import)
    client = FakeClient()

    returned = x402_helpers.apply_x402_max_payment_usd(client, "0.75")

    assert returned is client
    filtered = client.policy(2, [FakeRequirement(750_000), FakeRequirement(750_001)])
    assert [item.amount for item in filtered] == [750_000]


@pytest.mark.parametrize("cap", [0, -1, "nan", "inf", "bad"])
def test_x402_payment_cap_rejects_invalid_values(cap: float | str) -> None:
    with pytest.raises(ValueError, match="positive finite number"):
        x402_helpers._max_payment_atomic_units(cap)


def test_x402_payment_cap_requires_atomic_unit() -> None:
    with pytest.raises(ValueError, match="at least one USDC atomic unit"):
        x402_helpers._max_payment_atomic_units("0.0000001")


def test_x402_payment_cap_never_rounds_up() -> None:
    assert x402_helpers._max_payment_atomic_units("0." + "9" * 31) == 999_999

import { describe, expect, it, vi } from "vitest";

import { Browsers as V2Browsers } from "../src/v2/resources/browsers.js";
import { Browsers as V3Browsers } from "../src/v3/resources/browsers.js";

describe.each([
  ["v2", V2Browsers],
  ["v3", V3Browsers],
])("%s browser metadata", (_version, Browsers) => {
  it("sends metadata on create and as repeated-filter input on list", async () => {
    const http = {
      post: vi.fn(async () => ({})),
      get: vi.fn(async () => ({ items: [], totalItems: 0, pageNumber: 1, pageSize: 10 })),
    };
    const browsers = new Browsers(http as any);

    await browsers.create({
      metadata: { team: "sdk", env: "test" },
      pdfRendererEnabled: false,
      solveCaptchas: false,
      extensionIds: ["00000000-0000-0000-0000-000000000020"],
    });
    await browsers.list({ metadata: ["team", "env=test"] });

    expect(http.post).toHaveBeenCalledWith("/browsers", {
      metadata: { team: "sdk", env: "test" },
      pdfRendererEnabled: false,
      solveCaptchas: false,
      extensionIds: ["00000000-0000-0000-0000-000000000020"],
    });
    expect(http.get).toHaveBeenCalledWith("/browsers", {
      metadata: ["team", "env=test"],
    });
  });

  it("rejects more than 10 metadata entries", () => {
    const http = { post: vi.fn() };
    const browsers = new Browsers(http as any);
    const metadata = Object.fromEntries(
      Array.from({ length: 11 }, (_, index) => [`key-${index}`, `value-${index}`]),
    );

    expect(() => browsers.create({ metadata })).toThrow(
      "metadata supports at most 10 key-value pairs",
    );
    expect(http.post).not.toHaveBeenCalled();
  });
});
